import Foundation
import QuartzCore
import SwiftUI

/// World layout generated by art/bloom/sprites.py (bloom_world.json).
struct BloomWorld: Decodable {
    struct Island: Decodable {
        let id: Int
        let name: String
        let price: Int
        let cells: [[Int]]
        let origin: [Int]
        let spawn: [String: Int]
        let cap: Int
    }
    struct Bridge: Decodable {
        let tile: [Int]
        let vertical: Bool
        let a: Int
        let b: Int
    }
    let tile: Int
    let islands: [Island]
    let bridges: [Bridge]

    static func load() -> BloomWorld {
        guard let url = Bundle.main.url(forResource: "bloom_world", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let w = try? JSONDecoder().decode(BloomWorld.self, from: data) else {
            fatalError("bloom_world.json missing")
        }
        return w
    }
}

struct Cell: Hashable, Codable {
    var x: Int
    var y: Int
}

struct PlacedBuilding: Codable, Hashable {
    var kind: BuildKind
    var cell: Cell
}

/// One crafting queue per building kind. Items come out one by one.
struct CraftQueue: Codable {
    var recipe: String
    var left: Int
    var progress: Double   // seconds into the current item
}

struct BloomSave: Codable {
    var inv: [String: Int] = [:]
    var coins = 0
    var xp = 0
    var level = 1
    var owned: [Int] = [0]
    var buildings: [PlacedBuilding] = []
    var pick = 0
    var lucky = false
    var queues: [String: CraftQueue] = [:]
    var stats: [String: Int] = [:]
    var goal = 0
    var helpers: [String] = []
    var talents: [String] = []
    var finds: [String: Int] = [:]
    var savedAt = Date()
    // donate
    var gems = 0
    var founder = false
    var passUntil: Date?
    var jar = 0
    var jarTick = 0
    var fertUntil: Date?
    var adReadyAt: Date?
    // daily & rebirth (BloomMeta.swift)
    var life: [String: Int] = [:]          // lifetime counters, survive a new spring
    var loginDay = 0                       // next calendar day to claim (0...6, cycles)
    var loginClaimedOn: String?
    var dailyDate: String?
    var dailies: [DailyQuest] = []
    var dailyBonus = false
    var springs = 0                        // how many times the world was reborn
    var seeds = 0                          // eternal seeds to spend
    var eternal: [String: Int] = [:]       // eternal upgrade levels
    var bestLevel = 1
    // events, skins, offers (BloomEvents.swift)
    var eventWeek: String?
    var eventPoints = 0
    var eventFree: [Int] = []
    var eventPrem: [Int] = []
    var eventPass: String?                 // week the event pass was bought for
    var skins: [String] = []
    var skin: String?
    var starter = false
    var slot = false
    var tut = 0                            // onboarding step, 99 = done
    var achieved: [String] = []            // Game Center achievements already sent
    var fairDay: String?                   // day the fair orders were drawn for
    var fairOrders: [FairOrder] = []
    var fairDone: [Int] = []

    init() {}

    /// Tolerant decoding: fields added later default instead of wiping the save.
    init(from d: Decoder) throws {
        let c = try d.container(keyedBy: CodingKeys.self)
        inv = try c.decodeIfPresent([String: Int].self, forKey: .inv) ?? [:]
        coins = try c.decodeIfPresent(Int.self, forKey: .coins) ?? 0
        xp = try c.decodeIfPresent(Int.self, forKey: .xp) ?? 0
        level = try c.decodeIfPresent(Int.self, forKey: .level) ?? 1
        owned = try c.decodeIfPresent([Int].self, forKey: .owned) ?? [0]
        buildings = try c.decodeIfPresent([PlacedBuilding].self, forKey: .buildings) ?? []
        pick = try c.decodeIfPresent(Int.self, forKey: .pick) ?? 0
        lucky = try c.decodeIfPresent(Bool.self, forKey: .lucky) ?? false
        queues = try c.decodeIfPresent([String: CraftQueue].self, forKey: .queues) ?? [:]
        stats = try c.decodeIfPresent([String: Int].self, forKey: .stats) ?? [:]
        goal = try c.decodeIfPresent(Int.self, forKey: .goal) ?? 0
        helpers = try c.decodeIfPresent([String].self, forKey: .helpers) ?? []
        talents = try c.decodeIfPresent([String].self, forKey: .talents) ?? []
        finds = try c.decodeIfPresent([String: Int].self, forKey: .finds) ?? [:]
        savedAt = try c.decodeIfPresent(Date.self, forKey: .savedAt) ?? Date()
        gems = try c.decodeIfPresent(Int.self, forKey: .gems) ?? 0
        founder = try c.decodeIfPresent(Bool.self, forKey: .founder) ?? false
        passUntil = try c.decodeIfPresent(Date.self, forKey: .passUntil)
        jar = try c.decodeIfPresent(Int.self, forKey: .jar) ?? 0
        jarTick = try c.decodeIfPresent(Int.self, forKey: .jarTick) ?? 0
        fertUntil = try c.decodeIfPresent(Date.self, forKey: .fertUntil)
        adReadyAt = try c.decodeIfPresent(Date.self, forKey: .adReadyAt)
        life = try c.decodeIfPresent([String: Int].self, forKey: .life) ?? stats
        loginDay = try c.decodeIfPresent(Int.self, forKey: .loginDay) ?? 0
        loginClaimedOn = try c.decodeIfPresent(String.self, forKey: .loginClaimedOn)
        dailyDate = try c.decodeIfPresent(String.self, forKey: .dailyDate)
        dailies = try c.decodeIfPresent([DailyQuest].self, forKey: .dailies) ?? []
        dailyBonus = try c.decodeIfPresent(Bool.self, forKey: .dailyBonus) ?? false
        springs = try c.decodeIfPresent(Int.self, forKey: .springs) ?? 0
        seeds = try c.decodeIfPresent(Int.self, forKey: .seeds) ?? 0
        eternal = try c.decodeIfPresent([String: Int].self, forKey: .eternal) ?? [:]
        bestLevel = try c.decodeIfPresent(Int.self, forKey: .bestLevel) ?? level
        eventWeek = try c.decodeIfPresent(String.self, forKey: .eventWeek)
        eventPoints = try c.decodeIfPresent(Int.self, forKey: .eventPoints) ?? 0
        eventFree = try c.decodeIfPresent([Int].self, forKey: .eventFree) ?? []
        eventPrem = try c.decodeIfPresent([Int].self, forKey: .eventPrem) ?? []
        eventPass = try c.decodeIfPresent(String.self, forKey: .eventPass)
        skins = try c.decodeIfPresent([String].self, forKey: .skins) ?? []
        skin = try c.decodeIfPresent(String.self, forKey: .skin)
        starter = try c.decodeIfPresent(Bool.self, forKey: .starter) ?? false
        slot = try c.decodeIfPresent(Bool.self, forKey: .slot) ?? false
        // players who already had a save skip the tutorial
        tut = try c.decodeIfPresent(Int.self, forKey: .tut) ?? 99
        achieved = try c.decodeIfPresent([String].self, forKey: .achieved) ?? []
        fairDay = try c.decodeIfPresent(String.self, forKey: .fairDay)
        fairOrders = try c.decodeIfPresent([FairOrder].self, forKey: .fairOrders) ?? []
        fairDone = try c.decodeIfPresent([Int].self, forKey: .fairDone) ?? []
    }
}

enum BloomPanel: Equatable {
    case build
    case building(BuildKind)
    case buy(Int)
    case inventory
    case talents
    case album
    case shop
    case feedback
    case daily
    case spring
    case event
    case skins
    case menu
}

struct BloomToast: Identifiable, Equatable {
    let id = UUID()
    let title: String
    let subtitle: String
}

/// Game state and rules. The scene drives it; the HUD observes it.
@MainActor
final class BloomGame: ObservableObject {
    let world = BloomWorld.load()

    /// Not @Published: crafting progress ticks every frame, the HUD must only
    /// redraw on real changes, so `s` publishes from willSet and progress lives apart.
    /// Gathering changes it many times a second; the HUD redraws at most ~8 times a second
    /// (the first change after a quiet moment still shows at once, so taps feel instant).
    var s = BloomSave() { didSet { scheduleRedraw() } }
    private var redrawPending = false
    private var lastRedraw: CFTimeInterval = 0
    private func scheduleRedraw() {
        guard !redrawPending else { return }
        redrawPending = true
        let wait = max(0, 0.12 - (CACurrentMediaTime() - lastRedraw))
        DispatchQueue.main.asyncAfter(deadline: .now() + wait) { [weak self] in
            MainActor.assumeIsolated {
                guard let self else { return }
                self.redrawPending = false
                self.lastRedraw = CACurrentMediaTime()
                self.objectWillChange.send()
            }
        }
    }
    /// Seconds into the current item of each queue (not published).
    private(set) var progress: [String: Double] = [:]
    @Published var panel: BloomPanel? {
        didSet { if let p = panel, p != oldValue { Analytics.shared.track("bloom_panel", ["panel": String(describing: p)]) } }
    }
    @Published var combo = 0           // hits in the current chain
    @Published var toast: BloomToast?
    /// What the left context button offers right now (set by the scene).
    @Published var nearby: Nearby?

    enum Nearby: Equatable {
        case building(BuildKind)
        case island(Int)
    }

    /// Scene callbacks.
    var onIslandBought: ((Int) -> Void)?
    var onBuildingPlaced: ((PlacedBuilding) -> Void)?
    var onCrafted: ((BuildKind, BItem, Bool) -> Void)?
    var onGoalClaimed: (() -> Void)?
    var onRebirth: (() -> Void)?
    var onHelperAdded: ((String) -> Void)?
    var placeBuilding: ((BuildKind) -> Cell?)?

    private let key = "bloom.save.v2"
    private var lastHit: TimeInterval = 0

    init() {
        let args = ProcessInfo.processInfo.arguments
        if args.contains("-bloomReset") { UserDefaults.standard.removeObject(forKey: key) }
        if let d = UserDefaults.standard.data(forKey: key), let v = try? JSONDecoder().decode(BloomSave.self, from: d) {
            s = v
            for (k, q) in v.queues { progress[k] = q.progress }
            catchUp(seconds: Date().timeIntervalSince(v.savedAt))
        }
        if args.contains("-bloomRich") {
            for i in BItem.allCases { s.inv[i.rawValue, default: 0] += 40 }
            s.coins += 30000
            s.gems += 200
            s.level = max(s.level, 4)
        }
        #if DEBUG
        // App Store screenshots: a farm a few hours in (more islands, helpers, talents)
        if args.contains("-bloomShowcase") {
            // the same numbers in every language's screenshots
            s.level = 12
            s.xp = BloomContent.xpToNext(12) * 3 / 5
            s.coins = 24850
            s.gems = 340
            s.pick = max(s.pick, min(2, BloomContent.picks.count - 1))
            for id in [1, 2, 3, 4] where id < world.islands.count && !s.owned.contains(id) { s.owned.append(id) }
            s.helpers = Array(BloomContent.helperColors.prefix(max(s.helpers.count, min(3, BloomContent.maxHelpers))))
            for t in ["d1", "d2", "c1", "b1", "h1", "t1"] where !s.talents.contains(t) { s.talents.append(t) }
            s.tut = 99
        }
        // late game check: every island but the last two, level 14
        if args.contains("-bloomLate") {
            s.level = max(s.level, 14)
            for id in 0..<max(1, world.islands.count - 2) where !s.owned.contains(id) { s.owned.append(id) }
            for i in BItem.allCases { s.inv[i.rawValue, default: 0] += 60 }
            s.coins += 50000
            s.tut = 99
        }
        // -bloomAll: every island (biome checks and store screenshots)
        if args.contains("-bloomAll") {
            for id in 0..<world.islands.count where !s.owned.contains(id) { s.owned.append(id) }
        }
        #endif
    }

    // MARK: - inventory

    func count(_ i: BItem) -> Int { s.inv[i.rawValue] ?? 0 }
    var coins: Int { s.coins }
    var level: Int { s.level }
    var xp: Int { s.xp }
    var xpNeed: Int { BloomContent.xpToNext(s.level) }
    var pickTier: Int { s.pick }
    var pickLucky: Bool { s.lucky }
    var damage: Int {
        BloomContent.picks[s.pick].damage + (s.lucky ? 1 : 0) + (hasT("d1") ? 1 : 0) + (pageDone(2) ? 1 : 0)
    }
    var owned: Set<Int> { Set(s.owned) }
    var buildings: [PlacedBuilding] { s.buildings }

    func has(_ c: Cost, times: Int = 1) -> Bool { c.allSatisfy { count($0.0) >= $0.1 * times } }
    private func pay(_ c: Cost, times: Int = 1) { for (i, n) in c { s.inv[i.rawValue, default: 0] -= n * times } }

    func add(_ i: BItem, _ n: Int) {
        s.inv[i.rawValue, default: 0] += n
        bump("item." + i.rawValue, n)
    }

    /// Counts toward goals (this spring) and dailies/achievements (lifetime).
    func bump(_ key: String, _ n: Int = 1) {
        s.stats[key, default: 0] += n
        s.life[key, default: 0] += n
        if key.hasPrefix("gather.") { addEventPoints(n) }
        else if key.hasPrefix("craft.") { addEventPoints(2 * n) }
        else if key == "chest" { addEventPoints(15) }
    }
    func addCoins(_ n: Int) { s.coins += n }

    /// Items to show in the hotbar, in content order.
    var hotbar: [(BItem, Int)] { BItem.allCases.compactMap { count($0) > 0 ? ($0, count($0)) : nil } }

    // MARK: - gathering

    var comboStep: Int { min(BloomContent.maxCombo, 1 + combo / BloomContent.hitsPerStep) }

    /// Registers a hit and returns the combo multiplier (x1...x5).
    func registerHit(now: TimeInterval) -> Int {
        combo = now - lastHit <= comboWindow ? combo + 1 : 1
        lastHit = now
        if comboStep > (s.stats["combo"] ?? 0) { s.stats["combo"] = comboStep }
        return comboStep
    }

    func tickCombo(now: TimeInterval) {
        if combo > 0 && now - lastHit > comboWindow { combo = 0 }
    }

    /// Rolls the drops of a destroyed gatherable. Extra items for the combo.
    func roll(_ k: GatherKind, mult: Int) -> [(BItem, Int)] {
        var out: [(BItem, Int)] = []
        for d in k.drops where Double.random(in: 0..<1) < d.chance {
            out.append((d.item, Int.random(in: d.min...d.max)))
        }
        if mult > 1, let first = out.first { out[0] = (first.0, first.1 + (mult - 1) / BloomBalance.shared.comboBonusDiv) }
        if hasT("d4"), Double.random(in: 0..<1) < 0.15 { out = out.map { ($0.0, $0.1 * 2) } }
        if golden { out = out.map { ($0.0, $0.1 * 2) } }
        let extra = eternalBonus("loot")
        if extra > 0 { out = out.map { ($0.0, $0.1 + (Double.random(in: 0..<1) < extra ? 1 : 0)) } }
        if passActive { out = out.map { ($0.0, $0.1 + (Double.random(in: 0..<1) < BloomBalance.shared.shop.passDrop ? 1 : 0)) } }
        if eventIs("festival") { out = out.map { ($0.0, $0.1 + (Double.random(in: 0..<1) < 0.25 ? 1 : 0)) } }
        return out
    }

    /// Coins that fall out of a destroyed gatherable.
    func rollCoins(_ k: GatherKind, mult: Int) -> Int {
        let chance = (BloomBalance.shared.coinChance + 0.06 * Double(mult - 1) + (k.isStone ? 0.1 : 0)) * (hasT("t2") ? 1.5 : 1) * eternalMult("coins")
        let n = Double.random(in: 0..<1) < chance ? Int.random(in: 1...(k.isStone ? 3 : 2)) : 0
        return golden ? n * 2 : n
    }

    /// Returns new level if the xp made one.
    @discardableResult
    func gainXP(_ n0: Int) -> Int? {
        var n = pageDone(1) ? Int((Double(n0) * 1.15).rounded(.up)) : n0
        if passActive { n = Int((Double(n) * (1 + BloomBalance.shared.shop.passXP)).rounded(.up)) }
        n = Int((Double(n) * eternalMult("xp")).rounded(.up))
        s.xp += n
        var up: Int?
        while s.xp >= BloomContent.xpToNext(s.level) {
            s.xp -= BloomContent.xpToNext(s.level)
            s.level += 1
            up = s.level
        }
        if s.level > s.bestLevel { s.bestLevel = s.level }
        if let l = up {
            Analytics.shared.track("bloom_level", ["level": l, "minutes": playMinutes])
            showToast(BloomToast(title: tr("Уровень %@!", l), subtitle: BloomContent.levelUnlockText[l] ?? tr("Новое очко таланта")))
            Sfx.play(.levelUp)
        }
        return up
    }

    // MARK: - building

    func canBuild(_ b: BuildKind) -> Bool { s.level >= b.unlockLevel && has(cost(b)) && !isBuilt(b) }
    func cost(_ b: BuildKind) -> Cost { hasT("c2") ? b.cost.map { ($0.0, Int((Double($0.1) * 0.8).rounded(.up))) } : b.cost }
    func isBuilt(_ b: BuildKind) -> Bool { s.buildings.contains { $0.kind == b } }

    func build(_ b: BuildKind) {
        guard canBuild(b), let cell = placeBuilding?(b) else { Sfx.play(.error); return }
        Analytics.shared.track("bloom_build", ["kind": b.rawValue, "level": s.level])
        pay(cost(b))
        let pb = PlacedBuilding(kind: b, cell: cell)
        s.buildings.append(pb)
        panel = nil
        onBuildingPlaced?(pb)
        save()
    }

    // MARK: - crafting

    func queue(for b: BuildKind) -> CraftQueue? { s.queues[b.rawValue] }

    func craft(_ b: BuildKind, _ r: Recipe, times: Int) {
        let n = max(1, min(times, maxCraft(r)))
        guard has(r.cost, times: n) else { Sfx.play(.error); return }
        if var q = s.queues[b.rawValue], q.left > 0 {
            guard q.recipe == r.id else { Sfx.play(.error); return }
            q.left += n
            s.queues[b.rawValue] = q
        } else {
            s.queues[b.rawValue] = CraftQueue(recipe: r.id, left: n, progress: 0)
            progress[b.rawValue] = 0
        }
        pay(r.cost, times: n)
        Sfx.play(.select)
    }

    func maxCraft(_ r: Recipe) -> Int {
        r.cost.map { count($0.0) / $0.1 }.min() ?? 0
    }

    /// Advances crafting. Called by the scene each frame.
    func tick(dt: Double) {
        for b in BuildKind.allCases {
            guard let q = s.queues[b.rawValue], q.left > 0,
                  let r = b.recipes.first(where: { $0.id == q.recipe }) else { continue }
            var p = (progress[b.rawValue] ?? 0) + dt
            if p >= secs(r) {
                p -= secs(r)
                var nq = q
                nq.left -= 1
                if nq.left == 0 { p = 0 }
                s.queues[b.rawValue] = nq
                let n = hasT("c3") && Double.random(in: 0..<1) < 0.2 ? 2 : 1
                add(r.output, n)
                bump("craft." + r.output.rawValue, n)
                onCrafted?(b, r.output, n > 1)
            }
            progress[b.rawValue] = p
        }
    }

    private func catchUp(seconds: Double) {
        guard seconds > 0 else { return }
        for b in BuildKind.allCases {
            guard var q = s.queues[b.rawValue], q.left > 0,
                  let r = b.recipes.first(where: { $0.id == q.recipe }) else { continue }
            let p = progress[b.rawValue] ?? 0
            let done = min(q.left, Int((p + seconds) / secs(r)))
            q.left -= done
            progress[b.rawValue] = q.left > 0 ? (p + seconds).truncatingRemainder(dividingBy: secs(r)) : 0
            add(r.output, done)
            s.queues[b.rawValue] = q
        }
    }

    // MARK: - anvil

    var nextPick: PickTier? { s.pick + 1 < BloomContent.picks.count ? BloomContent.picks[s.pick + 1] : nil }

    func forgePick() {
        guard let p = nextPick, has(p.cost) else { Sfx.play(.error); return }
        pay(p.cost)
        s.pick += 1
        s.lucky = Double.random(in: 0..<1) < luckyChance
        onCrafted?(.anvil, .iron_bar, s.lucky)
        showToast(BloomToast(title: s.lucky ? tr("Удачная ковка!") : p.title,
                           subtitle: s.lucky ? tr("%@ +1 к удару", p.title) : tr("Удар: %@", damage)))
        Sfx.play(s.lucky ? .victory : .chest)
        save()
    }

    // MARK: - market

    func sell(_ i: BItem, all: Bool) {
        let n = all ? count(i) : min(count(i), 1)
        let coins = sellValue(i, n)
        guard n > 0, coins > 0 else { Sfx.play(.error); return }
        // only take as many as the coins pay for; the rest stays in the bag
        let used = min(n, Int((Double(coins) / sellPrice(i)).rounded(.up)))
        s.inv[i.rawValue] = count(i) - used
        s.coins += coins
        bump("sold", coins)
        Sfx.playThrottled(.coin, gap: 0.05)
    }

    // MARK: - islands

    func island(_ id: Int) -> BloomWorld.Island { world.islands[id] }

    func buy(_ id: Int) {
        let isl = island(id)
        guard !owned.contains(id), s.coins >= islandPrice(id) else { Sfx.play(.error); return }
        s.coins -= islandPrice(id)
        s.owned.append(id)
        Analytics.shared.track("bloom_island", ["id": id, "level": s.level, "minutes": playMinutes])
        // ask for a rating at a happy moment, never after a loss: right after the 3rd island blooms
        if s.owned.count == 3 { onAskReview?() }
        panel = nil
        nearby = nil
        onIslandBought?(id)
        showToast(BloomToast(title: tr(isl.name), subtitle: tr("Остров расцвёл!")))
        save()
    }

    // MARK: - stats & goals

    func gathered(_ k: GatherKind) {
        // the dew jar fills a little with every gathered thing
        s.jarTick += 1
        if s.jarTick % 25 == 0 { s.jar = min(BloomGame.jarCap, s.jar + 1) }
        let key: String
        switch k {
        case .tree, .pine, .palm: key = "gather.tree"
        case .rock, .rock_iron, .rock_gold, .crystal, .dune, .obsidian, .starstone: key = "gather.rock"
        case .bush_berry, .bush_cotton, .mushroom, .hive: key = "gather.bush"
        case .pond: key = "gather.pond"
        }
        bump(key)
    }

    func stat(_ key: String) -> Int {
        switch key {
        case "islands": return s.owned.count
        case "level": return s.level
        case "pick": return s.pick
        case "helpers": return s.helpers.count
        default:
            if key.hasPrefix("build."), let b = BuildKind(rawValue: String(key.dropFirst(6))) { return isBuilt(b) ? 1 : 0 }
            return s.stats[key] ?? 0
        }
    }

    var goalIndex: Int { s.goal }
    var goal: Goal? { s.goal < BloomContent.goals.count ? BloomContent.goals[s.goal] : nil }
    var goalProgress: Int { goal.map { min($0.target, stat($0.key)) } ?? 0 }
    var goalDone: Bool { goal.map { stat($0.key) >= $0.target } ?? false }

    func claimGoal() {
        guard let g = goal, goalDone else { return }
        Analytics.shared.track("bloom_goal", ["index": s.goal, "key": g.key, "minutes": playMinutes])
        s.goal += 1
        s.coins += g.coins
        Sfx.play(.victory)
        onGoalClaimed?()
        showToast(BloomToast(title: tr("Цель выполнена!"), subtitle: tr("+%@ монет", g.coins) + (g.xp > 0 ? tr(", +%@ опыта", g.xp) : "")))
        if g.xp > 0 { gainXP(g.xp) }
        save()
    }

    // MARK: - chests

    /// Loot of a treasure chest: coins and a few items of the islands you own.
    func openChest() -> (coins: Int, items: [(BItem, Int)]) {
        bump("chest")
        let tier = s.owned.count
        let bb = BloomBalance.shared
        let coins = Int.random(in: bb.chestCoinsMin...bb.chestCoinsMax) + tier * bb.chestCoinsPerIsland
        var pool: [BItem] = [.wood, .stone, .berry, .flower]
        if s.owned.contains(1) || s.owned.contains(3) { pool.append(.cotton) }
        if s.owned.contains(2) { pool += [.iron_ore, .brick] }
        if s.owned.contains(4) { pool += [.gold_ore, .iron_bar] }
        if s.owned.contains(5) { pool.append(.crystal) }
        if s.owned.contains(6) { pool += [.sand, .glass] }
        if s.owned.contains(7) { pool.append(.fish) }
        if s.owned.contains(8) { pool.append(.mushroom) }
        if s.owned.contains(9) { pool += [.honey, .jam] }
        if s.owned.contains(10) { pool.append(.obsidian) }
        if s.owned.contains(11) { pool.append(.stardust) }
        var items: [(BItem, Int)] = []
        for i in pool.shuffled().prefix(3) {
            let n = [.crystal, .gold_ore, .iron_bar, .glass, .jam, .obsidian, .stardust].contains(i) ? Int.random(in: 1...2) : Int.random(in: 3...6)
            items.append((i, n))
        }
        gainXP(6 + tier * 2)
        Sfx.play(.chest)
        return (coins, items)
    }

    // MARK: - helpers

    var helpers: [String] { s.helpers }
    var helperCost: Cost {
        let c = BloomContent.helperCost(s.helpers.count)
        return hasT("h1") ? c.map { ($0.0, Int((Double($0.1) * 0.7).rounded(.up))) } : c
    }
    var maxHelpers: Int { BloomContent.maxHelpers + (hasT("h4") ? 1 : 0) + (s.slot ? 1 : 0) }
    var canGrowHelper: Bool { s.helpers.count < maxHelpers && has(helperCost) }

    func growHelper() {
        guard canGrowHelper else { Sfx.play(.error); return }
        pay(helperCost)
        let free = BloomContent.helperColors.filter { !s.helpers.contains($0) }
        let c = free.randomElement() ?? "pink"
        s.helpers.append(c)
        onHelperAdded?(c)
        showToast(BloomToast(title: tr("Новый помощник!"), subtitle: (BloomContent.helperNames[c] ?? tr("Блумлинг")) + tr(" будет добывать с тобой")))
        Sfx.play(.levelUp)
        panel = nil
        save()
    }

    // MARK: - talents

    @Published var goldenUntil: Date?
    var golden: Bool { (goldenUntil ?? .distantPast) > Date() }
    var onTalentsChanged: (() -> Void)?

    func hasT(_ id: String) -> Bool { s.talents.contains(id) }
    var talentPoints: Int {
        max(0, (s.level - 1) - s.talents.reduce(0) { $0 + BloomTalents.talent($1).cost })
    }
    func canLearn(_ t: Talent) -> Bool {
        !hasT(t.id) && (t.requires.map(hasT) ?? true) && talentPoints >= t.cost
    }
    func learn(_ t: Talent) {
        guard canLearn(t) else { Sfx.play(.error); return }
        Analytics.shared.track("bloom_talent", ["id": t.id, "level": s.level])
        s.talents.append(t.id)
        Sfx.play(.levelUp)
        onTalentsChanged?()
        save()
    }

    var comboWindow: Double { BloomContent.comboWindow + (hasT("d3") ? 0.4 : 0) }
    var critChance: Double { BloomContent.critChance + (hasT("d2") ? 0.06 : 0) }
    var luckyChance: Double { BloomContent.luckyChance + (hasT("c4") ? 0.25 : 0) }
    func secs(_ r: Recipe) -> Double { r.seconds * (hasT("c1") ? 0.75 : 1) * (hasT("c5") ? 0.7 : 1) / eternalMult("craft") }
    /// What the market pays for `n` of an item (market rate, Торговец talent).
    func sellValue(_ i: BItem, _ n: Int) -> Int {
        Int(Double(n * i.price) * BloomBalance.shared.sellRate * (hasT("t1") ? 1.25 : 1) * eternalMult("coins") * (pageDone(3) ? 1.2 : 1) * (eventIs("fair") ? 1.5 : 1))
    }
    /// Price of one, for display (at least 1 when a stack would pay something).
    func sellPrice(_ i: BItem) -> Double { Double(i.price) * BloomBalance.shared.sellRate * (hasT("t1") ? 1.25 : 1) * eternalMult("coins") * (pageDone(3) ? 1.2 : 1) * (eventIs("fair") ? 1.5 : 1) }
    func islandPrice(_ id: Int) -> Int {
        let pr = BloomBalance.shared.islandPrices
        let p = id < pr.count ? pr[id] : island(id).price
        return hasT("t4") ? Int((Double(p) * 0.8).rounded()) : p
    }
    var chestChance: Double { BloomContent.chestChance * (hasT("t3") ? 2 : 1) * (golden ? 2 : 1) * (eventIs("starfall") ? 2 : 1) }
    var respawnInterval: Double {
        let b = BloomBalance.shared
        var iv = b.respawnSeconds / (1 + b.respawnPerIsland * Double(max(0, s.owned.count - 1)))
        if hasT("b2") { iv /= 1.4 }
        if s.founder { iv /= 1 + b.shop.founderRegrow }
        if fertActive { iv /= b.shop.fertilizerMult }
        iv /= eternalMult("regrow")
        if pageDone(4) { iv /= 1.2 }
        return iv
    }
    var flowerFactor: Int { hasT("b1") ? 2 : 1 }
    var goldenDuration: Double { GoldenHour.duration * (hasT("b4") ? 1.5 : 1) }
    var helperSpeed: CGFloat { hasT("h2") ? 1.4 : 1 }
    var helperDamage: Int { hasT("h3") ? 2 : 1 }
    var runSpeed: CGFloat { pageDone(0) ? 1.15 : 1 }

    // MARK: - shop & donate

    static let jarCap = 300
    /// Gem price of the in-game spends.
    static let goldenNowGems = 20
    static let coinSackGems = 50
    var gems: Int { s.gems }
    var isFounder: Bool { s.founder }
    var passUntil: Date? { passActive ? s.passUntil : nil }
    var passActive: Bool { (s.passUntil ?? .distantPast) > Date() }
    var fertUntil: Date? { fertActive ? s.fertUntil : nil }
    var fertActive: Bool { (s.fertUntil ?? .distantPast) > Date() }
    var jar: Int { s.jar }
    var adReadyAt: Date { s.adReadyAt ?? .distantPast }
    /// Coins in a sack: a quarter of the next island, so it always feels useful.
    var coinSack: Int {
        let next = (0..<world.islands.count).first { !owned.contains($0) }
        return max(200, (next.map { islandPrice($0) } ?? 2000) / 4)
    }
    /// Scene hooks: start (or extend) a golden hour; the founder's golden Bloomling arrives.
    var onGoldenRequested: ((Double) -> Void)?
    var onFounder: (() -> Void)?
    var onAskReview: (() -> Void)?
    /// Minutes of play in this save (from gathered things, about 2.5 s each): a cheap pacing clock for analytics.
    var playMinutes: Int { s.jarTick / 24 }

    func grant(_ p: ShopProduct) {
        Analytics.shared.track("bloom_purchase", ["product": p.rawValue, "level": s.level, "minutes": playMinutes])
        switch p {
        case .founder:
            guard !s.founder else { return }
            s.founder = true
            s.gems += BloomBalance.shared.shop.founderGems
            onFounder?()
            showToast(BloomToast(title: tr("Набор основателя"), subtitle: tr("Золотой блумлинг уже бежит к тебе!")))
        case .pass:
            s.passUntil = max(Date(), s.passUntil ?? Date()).addingTimeInterval(28 * 86400)
            showToast(BloomToast(title: tr("Пропуск цветения"), subtitle: tr("+25% добычи и опыта на 28 дней")))
        case .starter:
            guard !s.starter else { return }
            s.starter = true
            s.gems += 150
            // a fixed bag, not a random chest: nothing bought with money is random (no loot boxes)
            give(EventReward(coins: 12, gems: 0, chest: false, golden: false, skin: nil))
            add(.wood, 40)
            add(.stone, 40)
            if !s.skins.contains("mint") { s.skins.append("mint") }
            s.skin = "mint"
            showToast(BloomToast(title: tr("Стартовый набор"), subtitle: tr("Мятный облик уже на тебе!")))
        case .slot:
            guard !s.slot else { return }
            s.slot = true
            showToast(BloomToast(title: tr("Ещё одно место в питомнике"), subtitle: tr("Теперь можно вырастить ещё одного блумлинга")))
        case .eventPass:
            refreshEvent()
            s.eventPass = eventKey
            showToast(BloomToast(title: tr("Пропуск события"), subtitle: tr("Открыты все награды: %@", tr(event.title))))
        case .jar:
            s.gems += s.jar
            showToast(BloomToast(title: tr("Банка росы"), subtitle: tr("+%@ росинок", s.jar)))
            s.jar = 0
        default:
            s.gems += p.gems
            showToast(BloomToast(title: tr("+%@ росинок", p.gems), subtitle: tr("Спасибо, что поддерживаешь игру!")))
        }
        Sfx.play(.victory)
        save()
    }

    private func spend(_ n: Int, _ what: String = #function) -> Bool {
        guard s.gems >= n else { Sfx.play(.error); return false }
        s.gems -= n
        Analytics.shared.track("bloom_gems_spent", ["what": what, "gems": n, "level": s.level])
        return true
    }

    func buyGoldenNow() {
        guard spend(BloomGame.goldenNowGems) else { return }
        panel = nil
        onGoldenRequested?(BloomBalance.shared.shop.adGoldenSeconds)
        save()
    }

    func buyFertilizer() {
        let sh = BloomBalance.shared.shop
        guard spend(sh.fertilizerGems) else { return }
        s.fertUntil = max(Date(), s.fertUntil ?? Date()).addingTimeInterval(sh.fertilizerMinutes * 60)
        showToast(BloomToast(title: tr("Удобрение"), subtitle: tr("Всё растёт вдвое быстрее")))
        Sfx.play(.harvest)
        save()
    }

    func buyCoinSack() {
        let n = coinSack
        guard spend(BloomGame.coinSackGems) else { return }
        s.coins += n
        Sfx.play(.coin)
        showToast(BloomToast(title: tr("Мешок монет"), subtitle: tr("+%@ монет", n)))
        save()
    }

    /// Called after a rewarded ad was watched to the end.
    func rewardAd() {
        Analytics.shared.track("bloom_ad_reward", ["level": s.level])
        s.adReadyAt = Date().addingTimeInterval(BloomBalance.shared.shop.adGoldenCooldown)
        panel = nil
        onGoldenRequested?(BloomBalance.shared.shop.adGoldenSeconds)
        save()
    }

    // MARK: - album

    var finds: [String: Int] { s.finds }
    func pageDone(_ i: Int) -> Bool { BloomAlbum.pages[i].finds.allSatisfy { (s.finds[$0.id] ?? 0) > 0 } }

    /// Maybe a rare find from a destroyed gatherable: (id, isNew).
    func rollFind(_ k: GatherKind) -> (String, Bool)? {
        let chance = BloomAlbum.baseChance * (hasT("t5") ? 2 : 1) * (golden ? 1.5 : 1) * (eventIs("starfall") ? 2 : 1)
        guard Double.random(in: 0..<1) < chance else { return nil }
        let page = BloomAlbum.page(for: k)
        let f = BloomAlbum.pages[page].finds.randomElement()!.id
        let isNew = (s.finds[f] ?? 0) == 0
        s.finds[f, default: 0] += 1
        if isNew {
            let got = BloomAlbum.pages[page].finds.filter { (s.finds[$0.id] ?? 0) > 0 }.count
            if pageDone(page) {
                showToast(BloomToast(title: tr("Страница «%@» собрана!", BloomAlbum.pages[page].title), subtitle: BloomAlbum.pages[page].bonus))
                Sfx.play(.victory)
            } else {
                showToast(BloomToast(title: tr("Находка: %@", BloomAlbum.title(f)), subtitle: "\(BloomAlbum.pages[page].title): \(got)/5"))
            }
        } else {
            s.coins += BloomAlbum.duplicateCoins
        }
        bump("finds")
        if isNew { Analytics.shared.track("bloom_find", ["id": f, "minutes": playMinutes]) }
        return (f, isNew)
    }

    // MARK: - toasts (one at a time, the rest wait their turn)

    private var toastQueue: [BloomToast] = []

    func showToast(_ t: BloomToast) {
        #if DEBUG
        if ProcessInfo.processInfo.arguments.contains("-bloomShowcase") { return }  // clean store screenshots
        #endif
        if toast == nil { toast = t } else { toastQueue.append(t) }
    }

    func nextToast() {
        toast = toastQueue.isEmpty ? nil : toastQueue.removeFirst()
    }

    // MARK: - save

    private var gcAt = Date.distantPast

    func save() {
        if s.tut < 99 { advanceTutorial() }
        if Date() > gcAt {
            gcAt = Date().addingTimeInterval(20)
            BloomGameCenter.shared.sync(self)
        }
        var v = s
        v.savedAt = Date()
        for (k, p) in progress { v.queues[k]?.progress = p }
        if let d = try? JSONEncoder().encode(v) { UserDefaults.standard.set(d, forKey: key) }
    }
}
